<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Hash;
use Illuminate\Validation\Rule;
use App\Services\{Access,Records,Audit};
use App\Models\User;
class RecordController {
 private function gate(string $kind,bool $write=false):array{$d=Records::def($kind);if(in_array($kind,['pengguna','menu','rw','rt']))abort_unless(auth()->user()->isAdmin(),403);else{Access::menu($kind,$write?'ubah':'lihat');if($write)abort_unless(auth()->user()->isOperator(),403);if($kind==='warga'||$kind==='hunian')abort_if(auth()->user()->roleCode()==='WARGA',403);}return $d;}
 public function index(Request $r,string $kind){$d=$this->gate($kind);$q=Records::query($kind);if($r->filled('q')){$search=mb_substr($r->string('q')->toString(),0,100);$keys=array_keys($d['columns']);$column=in_array('nama',$keys)?'nama':(in_array('alamat',$keys)?'alamat':array_key_first($d['fields']));$q->where('x.'.$column,'like','%'.$search.'%');}return view('records',compact('d','kind')+['rows'=>$q->orderByDesc('x.id')->paginate(15)->withQueryString()]);}
 public function form(string $kind,?int $id=null){$d=$this->gate($kind,true);$row=$id?Records::query($kind)->where('x.id',$id)->first():null;abort_if($id&&!$row,404);$options=Records::options();$grants=$kind==='menu'&&$id?DB::table('hak_akses_menu')->where('menu_id',$id)->get()->keyBy('peran_id'):collect();return view('record-form',compact('d','kind','row','options','grants'));}
 public function save(Request $r,string $kind,?int $id=null){$d=$this->gate($kind,true);$old=$id?Records::query($kind)->where('x.id',$id)->first():null;abort_if($id&&!$old,404);$table=$d['table'];$exists=fn($t)=>Rule::exists($t,'id')->whereNull('deleted_at');$rules=match($kind){
 'warga'=>['nama'=>'required|string|max:150','nik'=>['nullable','digits:16',Rule::unique('warga','nik')->ignore($id)],'kartu_keluarga_id'=>['required',$exists('kartu_keluarga')],'tanggal_lahir'=>'nullable|date|before_or_equal:today','jenis_kelamin'=>'required|in:L,P','hubungan_keluarga'=>'required|in:kepala_keluarga,istri,suami,anak,lainnya','telepon'=>'nullable|string|max:25','status'=>'required|in:aktif,draf,pindah,meninggal'],
 'keluarga'=>['nomor_kk'=>['required','digits:16',Rule::unique('kartu_keluarga','nomor_kk')->ignore($id)],'hunian_id'=>['required',$exists('hunian')],'status'=>'required|in:aktif,nonaktif'],
 'hunian'=>['rt_id'=>['required',$exists('rt')],'alamat'=>'required|string|max:2000','jenis'=>'required|in:rumah,kontrakan,kos','nama_pemilik'=>'nullable|string|max:100'],
 'pengguna'=>['nama'=>'required|string|max:100','email'=>['required','email','max:191',Rule::unique('pengguna','email')->ignore($id)],'password'=>($id?'nullable':'required').'|string|min:6|max:100','peran_id'=>'required|exists:peran,id','jabatan'=>'nullable|in:Ketua RT,Perangkat RT,Ketua RW,Sekretaris RW','rt_id'=>['nullable',$exists('rt')],'rw_id'=>['nullable',$exists('rw')],'warga_id'=>['nullable',$exists('warga'),Rule::unique('pengguna','warga_id')->ignore($id)],'aktif'=>'required|boolean'],
 'menu'=>['nama'=>'required|string|max:100','kode'=>['required','alpha_dash','max:50',Rule::unique('menu','kode')->ignore($id)],'route'=>['required',Rule::in(array_keys(Records::navigation()))],'parent_id'=>['nullable',$exists('menu')],'urutan'=>'required|integer|min:0|max:999','aktif'=>'required|boolean','grants'=>'nullable|array','grants.*'=>'array'],
 'rw'=>['kode'=>['required','string','max:10',Rule::unique('rw','kode')->ignore($id)],'nama'=>'required|string|max:100','kelurahan'=>'required|string|max:100','kecamatan'=>'nullable|string|max:100','kota'=>'nullable|string|max:100'],
 'rt'=>['rw_id'=>['required',$exists('rw')],'nomor'=>['required','string','max:10',Rule::unique('rt','nomor')->where('rw_id',$r->input('rw_id'))->ignore($id)]]};
  $v=$r->validate($rules);$grants=$v['grants']??[];unset($v['grants']);
  if($kind==='warga'){Access::kk((int)$v['kartu_keluarga_id']);if(!$r->user()->isAdmin()&&$old&&$old->kartu_keluarga_id!=$v['kartu_keluarga_id'])abort(422,'Gunakan modul mutasi untuk perpindahan KK.');}
  if($kind==='keluarga'){Access::hunian((int)$v['hunian_id']);if($id&&$v['status']==='nonaktif')abort_if(DB::table('warga')->where('kartu_keluarga_id',$id)->where('status','aktif')->whereNull('deleted_at')->exists(),422,'KK masih memiliki anggota aktif. Gunakan mutasi atau perbarui anggota lebih dahulu.');}if($kind==='hunian')Access::rt((int)$v['rt_id']);
  if($kind==='menu'){abort_if($id&&($v['parent_id']??null)==$id,422,'Menu tidak dapat menjadi induknya sendiri.');if($old)abort_unless($v['kode']===$old->kode,422,'Kode menu yang sudah dibuat tidak diubah.');}
  if($kind==='pengguna'){$role=DB::table('peran')->find($v['peran_id'])->kode;if($role==='RT'){abort_unless(!empty($v['rt_id'])&&in_array($v['jabatan'],['Ketua RT','Perangkat RT']),422,'Peran RT memerlukan wilayah dan jabatan RT.');$v['rw_id']=$v['warga_id']=null;}elseif($role==='RW'){abort_unless(!empty($v['rw_id'])&&in_array($v['jabatan'],['Ketua RW','Sekretaris RW']),422,'Peran RW memerlukan wilayah dan jabatan RW.');$v['rt_id']=$v['warga_id']=null;}elseif($role==='WARGA'){abort_unless(!empty($v['warga_id']),422,'Pilih warga yang dihubungkan ke akun.');$v['rt_id']=$v['rw_id']=$v['jabatan']=null;}else{$v['rt_id']=$v['rw_id']=$v['warga_id']=$v['jabatan']=null;}
   if($old&&$old->id===auth()->id())abort_unless($role==='ADMINISTRATOR'&&$v['aktif'],422,'Akun Administrator yang sedang digunakan harus tetap aktif.');
   if(!empty($v['password']))$v['password_hash']=Hash::make($v['password']);unset($v['password']);
  }
  DB::transaction(function()use($kind,$table,$v,$id,$old,$grants){
   if($kind==='warga'){$kk=DB::table('kartu_keluarga')->where('id',$v['kartu_keluarga_id'])->lockForUpdate()->first();if($v['status']==='aktif'&&$v['hubungan_keluarga']==='kepala_keluarga'){abort_if(DB::table('warga')->where('kartu_keluarga_id',$kk->id)->where('hubungan_keluarga','kepala_keluarga')->where('status','aktif')->whereNull('deleted_at')->when($id,fn($q)=>$q->where('id','!=',$id))->exists(),422,'KK ini sudah memiliki kepala keluarga aktif.');}if($old&&$old->hubungan_keluarga==='kepala_keluarga'&&($old->kartu_keluarga_id!=$v['kartu_keluarga_id']||$v['hubungan_keluarga']!=='kepala_keluarga'||$v['status']!=='aktif'))abort_if(DB::table('warga')->where('kartu_keluarga_id',$old->kartu_keluarga_id)->where('id','!=',$id)->where('status','aktif')->whereNull('deleted_at')->exists(),422,'Tetapkan kepala keluarga pengganti melalui pembaruan KK sebelum menonaktifkan kepala keluarga.');}
   if($id){DB::table($table)->where('id',$id)->update($v+['updated_at'=>now()]);$recordId=$id;}else{$recordId=DB::table($table)->insertGetId($v+['created_at'=>now(),'updated_at'=>now()]);}
   if($kind==='menu')foreach(DB::table('peran')->get() as $role){$grant=$grants[$role->id]??[];DB::table('hak_akses_menu')->updateOrInsert(['peran_id'=>$role->id,'menu_id'=>$recordId],['lihat'=>isset($grant['lihat']),'tambah'=>isset($grant['tambah']),'ubah'=>isset($grant['ubah']),'hapus'=>isset($grant['hapus'])]);}
   Audit::record($id?'ubah':'tambah',$table,$recordId,$old,$v);
  });return redirect('/data/'.$kind)->with('success','Data berhasil disimpan.');
 }
 public function setHead(Request $r,int $id){$this->gate('keluarga',true);Access::kk($id);$v=$r->validate(['kepala_id'=>'required|integer|exists:warga,id']);DB::transaction(function()use($id,$v){DB::table('kartu_keluarga')->where('id',$id)->lockForUpdate()->first();$w=DB::table('warga')->where('id',$v['kepala_id'])->where('kartu_keluarga_id',$id)->where('status','aktif')->whereNull('deleted_at')->first();abort_unless($w,422,'Pilih anggota aktif pada kartu keluarga ini.');$old=DB::table('warga')->where('kartu_keluarga_id',$id)->where('hubungan_keluarga','kepala_keluarga')->where('status','aktif')->whereNull('deleted_at')->first();DB::table('warga')->where('kartu_keluarga_id',$id)->where('hubungan_keluarga','kepala_keluarga')->where('status','aktif')->whereNull('deleted_at')->update(['hubungan_keluarga'=>'lainnya','updated_at'=>now()]);DB::table('warga')->where('id',$w->id)->update(['hubungan_keluarga'=>'kepala_keluarga','updated_at'=>now()]);Audit::record('ganti_kepala_keluarga','kartu_keluarga',$id,$old,['kepala_id'=>$w->id,'nama'=>$w->nama]);});return back()->with('success','Kepala keluarga diperbarui dalam satu transaksi.');}
 public function destroy(string $kind,int $id){$d=$this->gate($kind,true);abort_unless(auth()->user()->isAdmin(),403);$row=Records::query($kind)->where('x.id',$id)->first();abort_unless($row,404);abort_if($kind==='pengguna'&&$id===auth()->id(),422,'Akun yang sedang digunakan tidak dapat dihapus.');
  DB::transaction(function()use($kind,$d,$id,$row){if($kind==='warga'){abort_if(DB::table('pengguna')->where('warga_id',$id)->where('aktif',true)->whereNull('deleted_at')->exists(),422,'Nonaktifkan akun warga terlebih dahulu.');if($row->hubungan_keluarga==='kepala_keluarga')abort_if(DB::table('warga')->where('kartu_keluarga_id',$row->kartu_keluarga_id)->where('id','!=',$id)->where('status','aktif')->whereNull('deleted_at')->exists(),422,'Kepala keluarga masih memiliki anggota aktif.');}
   if(in_array($kind,['rw','rt','hunian','keluarga'])){$refs=match($kind){'rw'=>['rt','rw_id'],'rt'=>['hunian','rt_id'],'hunian'=>['kartu_keluarga','hunian_id'],'keluarga'=>['warga','kartu_keluarga_id']};abort_if(DB::table($refs[0])->where($refs[1],$id)->whereNull('deleted_at')->exists(),422,'Masih ada data aktif yang terkait. Pindahkan atau nonaktifkan data turunannya dahulu.');}
   DB::table($d['table'])->where('id',$id)->update(['deleted_at'=>now(),'updated_at'=>now()]);Audit::record('hapus_logis',$d['table'],$id,$row);});return back()->with('success','Data dihapus dari daftar aktif; riwayat tetap tersimpan.');
 }
}
